const CACHE='stockholm-guide-gh-v6-english-photos';const CORE=['./english.js','./stockholm-free-en.html','./stockholm-free.html','./','./index.html','./style.css','./data.js','./app.js','./city-photos.js','./motion.js','./rays.js','./vendor/gsap.min.js','./vendor/ScrollTrigger.min.js','./vendor/lenis.min.js','./vendor/lenis.css','./icon.svg','./manifest.json','./icon-192.png','./icon-512.png'];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(CORE)));self.skipWaiting()});self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('stockholm-guide-gh-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match(new URL('./index.html',self.registration.scope).href):Response.error()))))});
